begin;
create function pg_temp.assert_true(ok boolean,message text) returns text language plpgsql as $$begin if ok is distinct from true then raise exception 'ASSERTION FAILED: %',message;end if;return message;end$$;
create function pg_temp.expect_error(query text,code text) returns boolean language plpgsql as $$begin execute query;return false;exception when others then if sqlstate<>code then raise exception 'Expected %, got %: %',code,sqlstate,sqlerrm;end if;return true;end$$;
grant execute on function pg_temp.assert_true(boolean,text),pg_temp.expect_error(text,text) to authenticated,service_role;
create temporary table execution_case_ids(key text primary key,id uuid);grant all on execution_case_ids to authenticated,service_role;
insert into execution_case_ids select 'work',id from private.work_orders where code='synthetic-cleaning';
insert into execution_case_ids select 'order',order_id from private.work_orders where code='synthetic-cleaning';
set local role authenticated;select set_config('request.jwt.claim.sub','a1000000-0000-0000-0000-000000000001',true);
insert into execution_case_ids values('case',public.execution_case_command((select id from execution_case_ids where key='order'),'report',jsonb_build_object('work_order_id',(select id from execution_case_ids where key='work'),'category','safety','severity','critical','priority','critical','description','Synthetic confidential safety concern','reason','Synthetic complaint'),'synthetic-confidential-report'));
select pg_temp.assert_true(public.read_service_case((select id from execution_case_ids where key='case'))->>'status'='open','Reporter receives an authorised restricted case projection');
select pg_temp.assert_true(not(public.read_service_case((select id from execution_case_ids where key='case')) ? 'owner_id'),'Customer case projection excludes confidential staffing and resolution internals');
select pg_temp.assert_true(pg_temp.expect_error('select public.process_execution_slas(25)','42501'),'Ordinary clients cannot run SLA worker');
select set_config('request.jwt.claim.sub','c1000000-0000-0000-0000-000000000011',true);
select pg_temp.assert_true(pg_temp.expect_error($q$select public.read_service_case((select id from execution_case_ids where key='case'))$q$,'42501'),'General operations read permission does not disclose sensitive investigation');
select set_config('request.jwt.claim.sub','a1000000-0000-0000-0000-000000000002',true);
select pg_temp.assert_true(pg_temp.expect_error($q$select public.read_service_case((select id from execution_case_ids where key='case'))$q$,'42501'),'Unrelated customer cannot access complaint');
reset role;select pg_sleep(1.1);
set local role service_role;select set_config('request.jwt.claim.role','service_role',true);select set_config('request.jwt.claim.sub','',true);
select pg_temp.assert_true(public.process_execution_slas(100)>=2,'Real case deadlines produce bounded SLA breaches');
select pg_temp.assert_true(public.process_execution_slas(100)=0,'SLA worker retry does not duplicate breach events');
reset role;
select pg_temp.assert_true((select count(*)=2 from private.execution_history where action='sla_breach' and details->>'case_id'=(select id::text from execution_case_ids where key='case')),'Each case deadline has exactly one immutable breach event');
select pg_temp.assert_true((select bool_and(actor_id is null and actor_type='system_worker') from private.execution_history where action='sla_breach'),'System breach processing does not fabricate human actors');
select pg_temp.assert_true((select status='escalated' from private.service_cases where id=(select id from execution_case_ids where key='case')),'Overdue case escalation is deterministic');
set local role authenticated;select set_config('request.jwt.claim.sub','d1000000-0000-0000-0000-000000000003',true);
select public.execution_case_command((select id from execution_case_ids where key='order'),'entry',jsonb_build_object('id',(select id from execution_case_ids where key='case'),'expected_revision',3,'kind','investigation','visibility','internal','content','Synthetic restricted investigation','reason','Investigate safely'),'synthetic-confidential-entry');
select public.execution_case_command((select id from execution_case_ids where key='order'),'propose_resolution',jsonb_build_object('id',(select id from execution_case_ids where key='case'),'expected_revision',4,'requirements','{"action":"Safety investigation concluded"}'::jsonb,'reason','Synthetic resolution'),'synthetic-confidential-propose');
select pg_temp.assert_true(pg_temp.expect_error($q$select public.execution_case_command((select id from execution_case_ids where key='order'),'resolve',jsonb_build_object('id',(select id from execution_case_ids where key='case'),'expected_revision',5,'reason','Self decision'),'synthetic-confidential-self')$q$,'42501'),'Complaint resolution requires an independent decision maker');
select set_config('request.jwt.claim.sub','d1000000-0000-0000-0000-000000000004',true);
select public.execution_case_command((select id from execution_case_ids where key='order'),'resolve',jsonb_build_object('id',(select id from execution_case_ids where key='case'),'expected_revision',5,'reason','Independent safety resolution'),'synthetic-confidential-resolve');
select pg_temp.assert_true(public.read_service_case((select id from execution_case_ids where key='case'))->>'status'='resolved','Independent case resolution preserves investigation evidence');
select set_config('request.jwt.claim.sub','a1000000-0000-0000-0000-000000000001',true);
select pg_temp.assert_true(jsonb_array_length(public.read_service_case((select id from execution_case_ids where key='case'))->'entries')=0,'Customer cannot read internal investigation entries');
select public.execution_case_command((select id from execution_case_ids where key='order'),'reopen',jsonb_build_object('id',(select id from execution_case_ids where key='case'),'expected_revision',6,'reason','New customer evidence'),'synthetic-confidential-reopen');
select pg_temp.assert_true(public.read_service_case((select id from execution_case_ids where key='case'))->>'status'='open','Reporter can explicitly reopen a resolved case');
reset role;
select pg_temp.assert_true((select count(*)=1 from private.service_case_entries where case_id=(select id from execution_case_ids where key='case')),'Reopening does not overwrite original investigation');
select pg_temp.assert_true((select count(*)=4 from private.sla_tracks where case_id=(select id from execution_case_ids where key='case')),'Reopening starts a new retained SLA cycle');
select pg_temp.assert_true(pg_temp.expect_error($q$update private.execution_history set reason='changed' where work_order_id=(select id from execution_case_ids where key='work')$q$,'55000'),'Execution and complaint history are append-only');
select pg_temp.assert_true(not has_function_privilege('anon','public.fulfilment_command(uuid,text,jsonb,text)','EXECUTE') and not has_function_privilege('authenticated','public.process_execution_slas(integer)','EXECUTE'),'Execution and worker RPC grants remain separated');
rollback;
